import static java.lang.System.*; 

Question 1
Find a number  in base 10 such that when it is written in base 7 and then interpreted as base 5, it results in 345	. Write your 
answer in the blank provided on your answer sheet for this question. 
Question 2
What is output by the code to the right? 
A)  15.5 
B)  15 
C)  15.0 
D)  NaN 
E)  Infinity 

int a = 5; 
double b = 2.5; 
int c = 4; 
double result = a++ + b * --c / (a % 3)  
  + +c - -b; 
out.println(result); 

Question 3
What is output by the code to the right? 
A)  "2\n2.5\" 
B)  "2\n2.5\\" 
C)  "2\n2.5\\"" 
D)  "2\n2.5\\"\" 
E)  Compile-time error 

out.print("\""); 
out.printf("%d", 10/4); 
out.print("\\n"); 
out.printf("%.1f", 10/4.0); 
out.print("\\\\"); 
out.printf("%s", "\""); 

Question 4
What is output by the code to the right? 
A)  truetruetruetrue 

B)  falsetruetruefalse 
C)  truetruetruefalse 

D)  falsetruefalsefalse 
E)  falsefalsefalsefalse 

String s = "Comp Sci Rocks!"; 
String s2 = new String("Comp Sci Rocks!"); 
String s3 = new String("Comp Sci Rocks!").intern(); 

out.print(s == s2); 
out.print(s == s3); 
out.print(s2 == s3); 
out.print(s.equals(s2)^s2.equals(s3)); 

Question 5
What is output by the code to the right? 
A)  true false 
B)  true true 
C)  false false 
D)  false true 
E)  There is no output due to an error. 
boolean a = false; 
boolean b = true; 
boolean c = false; 
boolean result = a || b && (c = true) ^ 
  (c = false); 
out.println(result + " " + c); 

Question 6
What is output by the code to the right? 
A)  2147483648|5 
B)  -2147483648|-2 
C)  -2147483648|5 
D)  2147483647|5 
int m = Integer.MIN_VALUE; 
out.println(Math.abs(m) + "|" + 
Math.floorMod(m, 7)); 
Question 7
What is output by the code to the right? 
A)  5.0 
B)  6.0 
C)  7.0 
D)  8.0 
E)  6 

int a = 4, b = 7, c = 3; 
double r = a++ * --b / (double)(c += a) + 
  (a % 3) - (b-- - ++c); 
out.println(r);

