int x = 1;
String s = "";

switch (x++) {
  case 1:
    if (++x == 3) s += "A";
    else s += "B";
  case 2:
    if (x++ == 3) s += "C";
    else s += "D";
    break;
  default:
    s += "E";
}

out.println(s + x);

